      CASE
        WHEN NOT _extract.status IN ('open', 'closed')
        THEN ARRAY['status_in_set']
        ELSE CAST(ARRAY[] AS TEXT[])
      END
    ) AS failed_rules,
    JSON_BUILD_OBJECT('group_id', _extract.group_id) AS key_values,
    _extract._raw AS raw,
