            'UTF8'
          )
        ),
        'hex'
      ) AS reject_id,
      'q__dups' AS source_relation,
      'q__dups->q_dup' AS mapping,
      1 AS mapping_version
    FROM {{ source('bronze', 'q__dups') }}
  ) AS _extract
  WHERE
    COALESCE(
      (
        _extract._branch_group_id_coercible
        OR _extract._branch_status_coercible
        OR (
